import{_ as a,o as e,c as r,a3 as s}from"./chunks/framework.CqzWVxDX.js";const o="/ems_simulate/assets/mms-packet.DG6cYogN.png",i="/ems_simulate/assets/goose-catch.tlEbSt7x.png",l="/ems_simulate/assets/goose-message.C3JFOYWf.png",d="/ems_simulate/assets/report-packet.78HEMd5n.png",S=JSON.parse('{"title":"IEC 61850 报文查看","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec61850/packet-view.md","filePath":"guide/protocols/iec61850/packet-view.md","lastUpdated":1786981506000}'),n={name:"guide/protocols/iec61850/packet-view.md"};function h(p,t,c,u,m,g){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="iec-61850-报文查看" tabindex="-1">IEC 61850 报文查看 <a class="header-anchor" href="#iec-61850-报文查看" aria-label="Permalink to &quot;IEC 61850 报文查看&quot;">​</a></h1><p>IEC 61850 涉及 <strong>MMS</strong>（TCP 102 端口）与 <strong>GOOSE</strong>（以太网二层组播）两类报文，EMS Simulate 均可实时抓取与解析。</p><h2 id="一、mms-报文" tabindex="-1">一、MMS 报文 <a class="header-anchor" href="#一、mms-报文" aria-label="Permalink to &quot;一、MMS 报文&quot;">​</a></h2><h3 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h3><p>在左侧设备树中选中 IEC61850 设备，点击&quot;<strong>报文</strong>&quot;图标（需开启 MMS 报文抓包或连接中自动捕获）。</p><h3 id="报文类型" tabindex="-1">报文类型 <a class="header-anchor" href="#报文类型" aria-label="Permalink to &quot;报文类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>报文</th><th>说明</th></tr></thead><tbody><tr><td>连接建立</td><td>ACSE 关联请求/响应（含认证协商）</td></tr><tr><td>Read / Write</td><td>数据读写请求与响应</td></tr><tr><td>GetNameList / GetNameListResponse</td><td>模型浏览（发现数据模型）</td></tr><tr><td>Report</td><td>报告上送（含数据集成员值）</td></tr><tr><td>File Directory / Open / Read / Write</td><td>文件服务</td></tr></tbody></table><h3 id="解析内容" tabindex="-1">解析内容 <a class="header-anchor" href="#解析内容" aria-label="Permalink to &quot;解析内容&quot;">​</a></h3><p>平台对 MMS 报文自动解析，展示：</p><ul><li><strong>服务类别</strong>：Read / Write / Report / File 等；</li><li><strong>对象引用</strong>：如 <code>IED1LD0/MMXU1.TotW.mag.f</code>；</li><li><strong>数据类型</strong>：浮点、整型、布尔、品质、时标；</li><li><strong>值</strong>：读写的数据值（含品质 q 与时标 t）。</li></ul><p><img src="'+o+`" alt=""></p><h2 id="二、goose-报文" tabindex="-1">二、GOOSE 报文 <a class="header-anchor" href="#二、goose-报文" aria-label="Permalink to &quot;二、GOOSE 报文&quot;">​</a></h2><h3 id="进入方式-1" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式-1" aria-label="Permalink to &quot;进入方式&quot;">​</a></h3><p>进入&quot;<strong>GOOSE 抓包</strong>&quot;功能：</p><ol><li>选择真实网卡；</li><li>点击开始抓包，监听二层组播报文；</li><li>实时解析并显示 GOOSE 控制块与数据集成员值。</li></ol><h3 id="goose-报文结构" tabindex="-1">GOOSE 报文结构 <a class="header-anchor" href="#goose-报文结构" aria-label="Permalink to &quot;GOOSE 报文结构&quot;">​</a></h3><p>GOOSE 使用以太网二层帧（默认组播 MAC 从 <code>01:0C:CD:01:00:00</code> 起），包含：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┬──────────┬─────────┬──────────────────────────────┐</span></span>
<span class="line"><span>│ 以太网头       │ APPID    │ 长度     │ APDU（GOOSE PDU，ASN.1 编码）   │</span></span>
<span class="line"><span>│ 目的/源 MAC   │ 2 字节   │ 2 字节  │ 控制块信息 + 数据集成员值       │</span></span>
<span class="line"><span>└──────────────┴──────────┴─────────┴──────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="goose-字段" tabindex="-1">GOOSE 字段 <a class="header-anchor" href="#goose-字段" aria-label="Permalink to &quot;GOOSE 字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>APPID</td><td>应用标识（区分数据集）</td></tr><tr><td>GOID</td><td>GOOSE 控制块标识</td></tr><tr><td>DATSET</td><td>数据集引用</td></tr><tr><td>ConfRev</td><td>配置版本号</td></tr><tr><td>T</td><td>报文时标</td></tr><tr><td>StNum</td><td>状态号（变位时 +1）</td></tr><tr><td>SqNum</td><td>序号（周期重发递增）</td></tr><tr><td>Test</td><td>测试标志</td></tr><tr><td>数据集成员</td><td>各成员的最新值（如开关位置、品质）</td></tr></tbody></table><h3 id="抓包解析" tabindex="-1">抓包解析 <a class="header-anchor" href="#抓包解析" aria-label="Permalink to &quot;抓包解析&quot;">​</a></h3><ul><li>实时显示每个 GOOSE 控制块的 <strong>StNum / SqNum</strong> 变化；</li><li>监视数据集成员值变化（如开关变位）；</li><li>支持过滤 APPID，便于多控制块场景下定位。</li></ul><h4 id="goose抓包" tabindex="-1">GOOSE抓包 <a class="header-anchor" href="#goose抓包" aria-label="Permalink to &quot;GOOSE抓包&quot;">​</a></h4><p><img src="`+i+'" alt=""></p><h4 id="goose报文详情" tabindex="-1">GOOSE报文详情 <a class="header-anchor" href="#goose报文详情" aria-label="Permalink to &quot;GOOSE报文详情&quot;">​</a></h4><p><img src="'+l+'" alt=""></p><h2 id="三、reports-报文" tabindex="-1">三、Reports 报文 <a class="header-anchor" href="#三、reports-报文" aria-label="Permalink to &quot;三、Reports 报文&quot;">​</a></h2><p>报告控制块上送的报告报文实时可见，包含：</p><ul><li>报告 ID、数据集引用；</li><li>触发原因：数据变化（dchg）、品质变化（qchg）、总召唤（GI）、周期（periodic）；</li><li>成员值：变化的数据对象值（含品质与时标）；</li><li>缓存 / 非缓存行为差异（BRCB 断链缓存、URCB 不缓存）。</li></ul><p><img src="'+d+'" alt=""></p><h2 id="排查技巧" tabindex="-1">排查技巧 <a class="header-anchor" href="#排查技巧" aria-label="Permalink to &quot;排查技巧&quot;">​</a></h2><ul><li><strong>MMS 连接失败</strong>：确认端口 102、IP 可达、认证密码一致；</li><li><strong>GOOSE 收不到</strong>：确认网卡、组播地址、APPID、VLAN 配置；</li><li><strong>报告不触发</strong>：核对数据集、触发条件（dchg/qchg/GI）与 RCB 使能状态；</li><li><strong>值不变但 SqNum 增长</strong>：正常周期重发；StNum 增长表示发生了变位事件。</li></ul>',32)])])}const O=a(n,[["render",h]]);export{S as __pageData,O as default};
